function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Blue='#335d92', BlueLt='#5c8dc5', Glow='#38bdf8';
  // digit 1
  px(14,8,6,16,O);
  px(15,9,4,14,Blue);
  px(15,9,4,1,BlueLt);
  px(12,11,4,2,Blue); px(13,10,2,1,Glow);
  px(12,21,10,2,Blue);

}
